mapper.update:
UPDATE t2000_complain
SET
complain_status_cd =
#{codeId}
WHERE
complain_id = #{complainID}

mapper.select:
SELECT COUNT(*) FROM t2000_complain c JOIN t2000_complain_category g ON g.complain_category_id = c.complain_category_id JOIN t2000_complain_user r ON r.complainuser_no = c.complainuser_no LEFT JOIN t1000_account a ON a.account_id = c.account_id LEFT JOIN t1000_user u ON u.user_no = a.user_no WHERE c.complain_category_id = #{complainCategoryId}
AND c.complain_status_cd = #{status}
AND r.complainuser_name LIKE '%' || #{complainUserName} || '%'
AND u.user_name LIKE '%' || #{manager} || '%'
AND c.deadline_dt >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND c.deadline_dt < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND c.rcpt_dt >= TO_DATE(#{startDate}, 'YYYY-MM-DD') AND c.rcpt_dt < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
